import{_ as i,o as l,c,ag as t}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"ecc-code-review","description":"","frontmatter":{},"headers":[],"relativePath":"commands/ecc-ecc-code-review.md","filePath":"commands/ecc-ecc-code-review.md"}'),a={name:"commands/ecc-ecc-code-review.md"};function o(d,e,r,n,s,h){return l(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="ecc-code-review" tabindex="-1">ecc-code-review <a class="header-anchor" href="#ecc-code-review" aria-label="Permalink to &quot;ecc-code-review&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>ecc-code-review</td></tr><tr><td>說明</td><td>對未提交的變更進行全面的安全與品質審查。呼叫 ecc-code-reviewer agent。</td></tr><tr><td>系列</td><td>ECC</td></tr><tr><td>來源檔案</td><td><code>commands/ecc-code-review.md</code></td></tr></tbody></table><hr><h1 id="程式碼審查" tabindex="-1">程式碼審查 <a class="header-anchor" href="#程式碼審查" aria-label="Permalink to &quot;程式碼審查&quot;">​</a></h1><p>此指令會呼叫 <strong>ecc-code-reviewer</strong> agent，對未提交的變更進行全面的安全性與品質審查。</p><h2 id="此指令的功能" tabindex="-1">此指令的功能 <a class="header-anchor" href="#此指令的功能" aria-label="Permalink to &quot;此指令的功能&quot;">​</a></h2><ol><li><p>取得變更的檔案：git diff --name-only HEAD</p></li><li><p>對每個變更的檔案，檢查：</p></li></ol><p><strong>安全性問題（CRITICAL）：</strong></p><ul><li>硬編碼的憑證、API 金鑰、令牌</li><li>SQL injection 漏洞</li><li>XSS 漏洞</li><li>缺少輸入驗證</li><li>不安全的相依套件</li><li>路徑穿越風險</li></ul><p><strong>程式碼品質（HIGH）：</strong></p><ul><li>超過 50 行的函式</li><li>超過 800 行的檔案</li><li>巢狀深度超過 4 層</li><li>缺少錯誤處理</li><li>console.log 陳述式</li><li>TODO/FIXME 注釋</li><li>公開 API 缺少 JSDoc</li></ul><p><strong>最佳實踐（MEDIUM）：</strong></p><ul><li>變更模式（改用不可變模式）</li><li>程式碼/注釋中使用 emoji</li><li>新程式碼缺少測試</li><li>無障礙問題（a11y）</li></ul><ol start="3"><li><p>產生報告，包含：</p><ul><li>嚴重程度：CRITICAL、HIGH、MEDIUM、LOW</li><li>檔案位置與行號</li><li>問題描述</li><li>建議修正方案</li></ul></li><li><p>若發現 CRITICAL 或 HIGH 問題則阻擋提交</p></li></ol><p>絕不核准含有安全性漏洞的程式碼！</p><h2 id="使用時機" tabindex="-1">使用時機 <a class="header-anchor" href="#使用時機" aria-label="Permalink to &quot;使用時機&quot;">​</a></h2><p>以下情況請使用 <code>/ecc-code-review</code>：</p><ul><li>撰寫或修改程式碼之後</li><li>建立 commit 之前</li><li>開啟 merge request 之前</li><li>完成功能實作之後</li></ul><h2 id="與其他指令的整合" tabindex="-1">與其他指令的整合 <a class="header-anchor" href="#與其他指令的整合" aria-label="Permalink to &quot;與其他指令的整合&quot;">​</a></h2><ul><li>實作前使用 <code>/ecc-plan</code> 規劃</li><li>使用 <code>/ecc-tdd</code> 進行測試驅動開發</li><li>若審查期間出現建置錯誤，使用 <code>/ecc-build-fix</code></li><li>使用 <code>/ecc-security-review</code> 進行更深入的安全性分析</li></ul><h2 id="相關-agent" tabindex="-1">相關 Agent <a class="header-anchor" href="#相關-agent" aria-label="Permalink to &quot;相關 Agent&quot;">​</a></h2><p>此指令會呼叫位於下列路徑的 <code>ecc-code-reviewer</code> agent： <code>~/.claude/agents/ecc-code-reviewer.md</code></p>',22)])])}const m=i(a,[["render",o]]);export{u as __pageData,m as default};
